151	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
152		fs := newFlagSet("handoff", stderr)
153		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
154		request := fs.String("request", "", "交接请求号（用于去重）")
155		from := fs.String("from", "", "源站点")
156		to := fs.String("to", "", "目的站点")
157		var parcels stringList
158		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
159		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
160			return code
161		}
162	
163		cleanReq, err := cleanID("请求号", *request)
164		if err != nil {
165			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
166			return exitBusiness
167		}
168		cleanFrom, err := cleanID("源站点", *from)
169		if err != nil {
170			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
171			return exitBusiness
172		}
173		cleanTo, err := cleanID("目的站点", *to)
174		if err != nil {
175			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
176			return exitBusiness
177		}
178		if len(parcels) == 0 {
179			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
180			return exitBusiness
181		}
182		cleanParcels := make([]string, 0, len(parcels))
183		seen := make(map[string]bool, len(parcels))
184		for _, raw := range parcels {
185			id, err := cleanID("包裹编号", raw)
186			if err != nil {
187				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
188				return exitBusiness
189			}
190			if seen[id] {
191				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
192				return exitBusiness
193			}
194			seen[id] = true
195			cleanParcels = append(cleanParcels, id)
196		}
197		if cleanFrom == cleanTo {
198			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
199			return exitBusiness
200		}
201	
202		store, err := Open(dataFile)
203		if err != nil {
204			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
205			return exitBusiness
206		}
207		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
208		if err != nil {
209			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
210			return exitBusiness
211		}
212	
213		headline := "交接成功"
214		if replayed {
215			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
216		}
217		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
218			headline, result.Request, result.From, result.To, len(result.Parcels))
219		for _, id := range result.Parcels {
220			fmt.Fprintf(stdout, "  - %s\n", id)
221		}
222		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
223		return exitOK
224	}
