1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// 包裹状态。
15	const (
16		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
17		statusInStation = "在站"
18		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
19		statusDelivering = "配送中"
20		// statusSigned 表示包裹已签收（回执结果为签收）。
21		statusSigned = "已签收"
22		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
23		statusFrozen = "异常冻结"
24	)
25	
26	// 回执结果。
27	const (
28		resultSigned = "签收"
29		resultFailed = "失败"
30	)
31	
32	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
33	type Event struct {
34		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回
35		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回为批次出发站）
36		Time       time.Time `json:"time"`                 // 发生时间
37		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回请求号（收件、出站记录为空）
38		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
39		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）或中止原因（仅收回记录有）
40		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
41		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回记录有）
42		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站记录有）
43		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
44		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
45		Incident string `json:"incident,omitempty"`
46		Note     string `json:"note,omitempty"`
47	}
48	
49	// Parcel 是一件包裹的台账信息。
50	type Parcel struct {
51		ID         string    `json:"id"`
52		Station    string    `json:"station"`    // 当前归属站点
53		Status     string    `json:"status"`     // 当前状态
54		Registered time.Time `json:"registered"` // 收件时间
55		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
56	}
57	
58	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
59	type HandoffResult struct {
60		Request    string    `json:"request"`
61		From       string    `json:"from"`
62		To         string    `json:"to"`
63		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
64		Time       time.Time `json:"time"`
65		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
66	}
67	
68	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
69	type ReturnResult struct {
70		Request string    `json:"request"` // 退回请求号
71		Handoff string    `json:"handoff"` // 被退回的原交接请求号
72		From    string    `json:"from"`    // 退回源站（原交接目的站）
73		To      string    `json:"to"`      // 退回目的站（原交接源站）
74		Reason  string    `json:"reason"`
75		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
76		Time    time.Time `json:"time"`
77	}
78	
79	// ReceiptEntry 是批次内一件包裹的回执记录。
80	type ReceiptEntry struct {
81		Request string    `json:"request"`          // 回执请求号
82		Result  string    `json:"result"`           // 签收 | 失败
83		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
84		Time    time.Time `json:"time"`
85	}
86	
87	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
88	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
89	type BatchResult struct {
90		Batch    string                   `json:"batch"`
91		Station  string                   `json:"station"`  // 出发站
92		Courier  string                   `json:"courier"`  // 配送员
93		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
94		Time     time.Time                `json:"time"`     // 出站时间
95		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
96		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
97		AbortedBy string `json:"abortedBy,omitempty"`
98	}
99	
100	// Done 报告批次是否已完成（全部成员均已回执）。
101	func (b *BatchResult) Done() bool { return len(b.Receipts) == len(b.Parcels) }
102	
103	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
104	type ReceiptResult struct {
105		Request string    `json:"request"` // 回执请求号
106		Batch   string    `json:"batch"`   // 所属配送批次号
107		Parcel  string    `json:"parcel"`  // 包裹编号
108		Result  string    `json:"result"`  // 签收 | 失败
109		Reason  string    `json:"reason,omitempty"`
110		Time    time.Time `json:"time"`
111	}
112	
113	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
114	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
115	type FreezeResult struct {
116		Incident string    `json:"incident"` // 异常单号
117		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
118		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
119		Reason   string    `json:"reason"`   // 清理后的冻结原因
120		Time     time.Time `json:"time"`     // 冻结时间
121		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
122		ReleasedBy string `json:"releasedBy,omitempty"`
123	}
124	
125	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
126	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
127	type UnfreezeResult struct {
128		Request  string    `json:"request"`  // 解除请求号
129		Incident string    `json:"incident"` // 被解除的异常单号
130		Parcel   string    `json:"parcel"`   // 对应包裹编号
131		Note     string    `json:"note"`     // 清理后的处理说明
132		Time     time.Time `json:"time"`     // 解除时间
133	}
134	
135	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
136	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
137	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
138	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
139	type AbortResult struct {
140		Request string    `json:"request"` // 中止请求号
141		Batch   string    `json:"batch"`   // 被中止的配送批次号
142		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
143		Reason  string    `json:"reason"`  // 清理后的中止原因
144		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
145		Time    time.Time `json:"time"`    // 中止时间
146	}
147	
148	// ledgerFile 是本地数据文件的磁盘结构。
149	type ledgerFile struct {
150		Version   int                        `json:"version"`
151		Parcels   map[string]*Parcel         `json:"parcels"`
152		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
153		Returns   map[string]*ReturnResult   `json:"returns"`
154		Batches   map[string]*BatchResult    `json:"batches"`
155		Receipts  map[string]*ReceiptResult  `json:"receipts"`
156		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
157		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
158		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
159	}
160	
161	// Store 是一个数据文件对应的包裹站点交接台账。
162	type Store struct {
163		path string
164		data ledgerFile
165	}
166	
167	var (
168		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
169		ErrCorrupt = errors.New("数据文件已损坏")
170		// ErrNotFound 表示包裹编号在台账中不存在。
171		ErrNotFound = errors.New("包裹不存在")
172	)
173	
174	// Open 打开（或在文件不存在时建立）一个本地台账。
175	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
176	func Open(path string) (*Store, error) {
177		s := &Store{path: path}
178		raw, err := os.ReadFile(path)
179		if err != nil {
180			if os.IsNotExist(err) {
181				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
182					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
183					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{}}
184				return s, nil
185			}
186			return nil, fmt.Errorf("读取数据文件失败: %w", err)
187		}
188		if len(bytes.TrimSpace(raw)) == 0 {
189			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
190		}
191		if err := json.Unmarshal(raw, &s.data); err != nil {
192			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
193		}
194		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
195			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
196		}
197		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort 相关字段：按空表处理，无需手工修改。
198		if s.data.Returns == nil {
199			s.data.Returns = map[string]*ReturnResult{}
200		}
201		if s.data.Batches == nil {
202			s.data.Batches = map[string]*BatchResult{}
203		}
204		if s.data.Receipts == nil {
205			s.data.Receipts = map[string]*ReceiptResult{}
206		}
207		if s.data.Freezes == nil {
208			s.data.Freezes = map[string]*FreezeResult{}
209		}
210		if s.data.Unfreezes == nil {
211			s.data.Unfreezes = map[string]*UnfreezeResult{}
212		}
213		if s.data.Aborts == nil {
214			s.data.Aborts = map[string]*AbortResult{}
215		}
216		for _, b := range s.data.Batches {
217			if b != nil && b.Receipts == nil {
218				b.Receipts = map[string]*ReceiptEntry{}
219			}
220		}
221		if err := s.data.validate(); err != nil {
222			return nil, err
223		}
224		return s, nil
225	}
226	
227	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
228	func (l *ledgerFile) validate() error {
229		for id, p := range l.Parcels {
230			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
231				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
232			}
233			switch p.Status {
234			case statusInStation, statusDelivering, statusSigned, statusFrozen:
235			default:
236				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
237			}
238			for i, e := range p.Trail {
239				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
240					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
241				}
242				if e.Op == "退回" {
243					if e.Request == "" || e.Reason == "" || e.From == "" {
244						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
245					}
246					if _, ok := l.Handoffs[e.RefRequest]; !ok {
247						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
248					}
249				}
250				if e.Op == "出站" {
251					if e.Batch == "" || e.Courier == "" {
252						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
253					}
254					if _, ok := l.Batches[e.Batch]; !ok {
255						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
256					}
257				}
258				if e.Op == "回执" {
259					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
260						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
261					}
262					if e.Result == resultFailed && e.Reason == "" {
263						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
264					}
265					if _, ok := l.Batches[e.Batch]; !ok {
266						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
267					}
268				}
269				if e.Op == "收回" {
270					if e.Batch == "" || e.Request == "" || e.Reason == "" {
271						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
272					}
273					a, ok := l.Aborts[e.Request]
274					if !ok {
275						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
276					}
277					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
278						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
279					}
280					inAbort := false
281					for _, pid := range a.Parcels {
282						if pid == id {
283							inAbort = true
284							break
285						}
286					}
287					if !inAbort {
288						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
289					}
290				}
291				if e.Op == "冻结" {
292					if e.Incident == "" || e.Reason == "" {
293						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
294					}
295					f, ok := l.Freezes[e.Incident]
296					if !ok {
297						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
298					}
299					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
300						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
301					}
302				}
303				if e.Op == "解除冻结" {
304					if e.Incident == "" || e.Request == "" || e.Note == "" {
305						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
306					}
307					f, ok := l.Freezes[e.Incident]
308					if !ok {
309						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
310					}
311					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
312						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
313					}
314					u, ok := l.Unfreezes[e.Request]
315					if !ok || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
316						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
317					}
318				}
319			}
320		}
321		for req, h := range l.Handoffs {
322			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
323				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
324			}
325			for _, id := range h.Parcels {
326				if _, ok := l.Parcels[id]; !ok {
327					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
328				}
329			}
330			if h.ReturnedBy != "" {
331				r, ok := l.Returns[h.ReturnedBy]
332				if !ok || r.Handoff != req {
333					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
334				}
335			}
336		}
337		for req, r := range l.Returns {
338			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
339				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
340				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
341			}
342			h, ok := l.Handoffs[r.Handoff]
343			if !ok {
344				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
345			}
346			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
347				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
348			}
349			for _, id := range r.Parcels {
350				if _, ok := l.Parcels[id]; !ok {
351					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
352				}
353			}
354		}
355		for id, b := range l.Batches {
356			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
357				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
358			}
359			seen := make(map[string]bool, len(b.Parcels))
360			for _, pid := range b.Parcels {
361				if seen[pid] {
362					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
363				}
364				seen[pid] = true
365				if _, ok := l.Parcels[pid]; !ok {
366					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
367				}
368			}
369			for pid, e := range b.Receipts {
370				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
371					(e.Result != resultSigned && e.Result != resultFailed) ||
372					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
373					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
374				}
375				rc, ok := l.Receipts[e.Request]
376				if !ok || rc.Batch != id || rc.Parcel != pid {
377					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
378				}
379			}
380			if b.AbortedBy != "" {
381				a, ok := l.Aborts[b.AbortedBy]
382				if !ok || a.Batch != id {
383					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
384				}
385			}
386		}
387		for req, rc := range l.Receipts {
388			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
389				(rc.Result != resultSigned && rc.Result != resultFailed) ||
390				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
391				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
392			}
393			b, ok := l.Batches[rc.Batch]
394			if !ok {
395				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
396			}
397			e, ok := b.Receipts[rc.Parcel]
398			if !ok || e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) {
399				return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
400			}
401		}
402		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序），且每件收回包裹的
403		// 轨迹中都有与该中止请求一致的收回记录；中止记录与收回轨迹不一致即损坏。
404		for req, a := range l.Aborts {
405			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
406				len(a.Parcels) == 0 || a.Time.IsZero() {
407				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
408			}
409			b, ok := l.Batches[a.Batch]
410			if !ok {
411				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
412			}
413			if b.AbortedBy != req {
414				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
415			}
416			if a.Station != b.Station {
417				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
418			}
419			expect := make([]string, 0, len(b.Parcels))
420			for _, pid := range b.Parcels {
421				if _, done := b.Receipts[pid]; !done {
422					expect = append(expect, pid)
423				}
424			}
425			if len(expect) != len(a.Parcels) {
426				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
427			}
428			for i := range expect {
429				if expect[i] != a.Parcels[i] {
430					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
431				}
432			}
433			for _, pid := range a.Parcels {
434				p, ok := l.Parcels[pid]
435				if !ok {
436					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
437				}
438				found := false
439				for _, e := range p.Trail {
440					if e.Op == "收回" && e.Request == req {
441						found = true
442						break
443					}
444				}
445				if !found {
446					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
447				}
448			}
449		}
450		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
451		// 再核对两张结果表与包裹当前状态的对应关系。
452		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
453		for id, p := range l.Parcels {
454			var open string
455			for i, e := range p.Trail {
456				switch e.Op {
457				case "冻结":
458					if open != "" {
459						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
460							ErrCorrupt, id, i+1, open)
461					}
462					open = e.Incident
463				case "解除冻结":
464					if open != e.Incident {
465						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
466							ErrCorrupt, id, i+1, e.Incident, open)
467					}
468					open = ""
469				}
470			}
471			if p.Status == statusFrozen && open == "" {
472				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
473			}
474			if p.Status != statusFrozen && open != "" {
475				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
476			}
477			if open != "" {
478				openIncident[id] = open
479			}
480		}
481		for no, f := range l.Freezes {
482			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
483				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
484			}
485			p, ok := l.Parcels[f.Parcel]
486			if !ok {
487				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
488			}
489			if f.ReleasedBy == "" && p.Station != f.Station {
490				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
491					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
492			}
493			if f.ReleasedBy != "" {
494				u, ok := l.Unfreezes[f.ReleasedBy]
495				if !ok || u.Incident != no || u.Parcel != f.Parcel {
496					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
497				}
498			}
499		}
500		activeByParcel := make(map[string]string)
501		for req, u := range l.Unfreezes {
502			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
503				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
504			}
505			f, ok := l.Freezes[u.Incident]
506			if !ok {
507				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
508			}
509			if f.Parcel != u.Parcel {
510				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
511			}
512			if f.ReleasedBy != req {
513				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
514			}
515		}
516		for no, f := range l.Freezes {
517			if f.ReleasedBy != "" {
518				continue
519			}
520			if other, dup := activeByParcel[f.Parcel]; dup {
521				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
522			}
523			activeByParcel[f.Parcel] = no
524			if openIncident[f.Parcel] != no {
525				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
526					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
527			}
528			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
529				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
530			}
531		}
532		return nil
533	}
