559	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
560	func (s *Store) Query(id string) (*Parcel, error) {
561		p, ok := s.data.Parcels[id]
562		if !ok {
563			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
564		}
565		return p, nil
566	}
