580	// Handoff 提交一次多件包裹的站点交接。
581	//
582	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
583	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
584	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
585	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
586	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
587		if saved, ok := s.data.Handoffs[request]; ok {
588			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
589				return saved, true, nil
590			}
591			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
592		}
593	
594		// 首次提交：先做全部校验，任何一件不满足都整体失败。
595		for _, id := range parcels {
596			p, ok := s.data.Parcels[id]
597			if !ok {
598				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
599			}
600			if p.Station != from {
601				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
602			}
603			if inc := activeFreeze(p); inc != "" {
604				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
605			}
606			if p.Status != statusInStation {
607				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
608			}
609		}
610	
611		res := &HandoffResult{
612			Request: request,
613			From:    from,
614			To:      to,
615			Parcels: append([]string(nil), parcels...),
616			Time:    now,
617		}
618		s.data.Handoffs[request] = res
619	
620		// 记录旧值，落盘失败时整体回滚。
621		prev := make(map[string]struct {
622			station string
623			trail   []Event
624		}, len(parcels))
625		for _, id := range parcels {
626			p := s.data.Parcels[id]
627			prev[id] = struct {
628				station string
629				trail   []Event
630			}{p.Station, append([]Event(nil), p.Trail...)}
631			p.Station = to
632			p.Status = statusInStation
633			p.Trail = append(p.Trail, Event{
634				Op:      "交接",
635				Station: to,
636				Request: request,
637				Time:    now,
638			})
639		}
640	
641		if err := s.save(); err != nil {
642			delete(s.data.Handoffs, request)
643			for id, old := range prev {
644				p := s.data.Parcels[id]
645				p.Station = old.station
646				p.Trail = old.trail
647			}
648			return nil, false, err
649		}
650		return res, false, nil
651	}
652	
653	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
654	//
655	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
656	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
657	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
658	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
659	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
660	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
661	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
662	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
663		if saved, ok := s.data.Returns[request]; ok {
664			if saved.Handoff == handoffReq && saved.Reason == reason {
665				return saved, true, nil
666			}
667			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
668				request, saved.Handoff, saved.Reason)
669		}
670	
671		h, ok := s.data.Handoffs[handoffReq]
672		if !ok {
673			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
674		}
675		if h.ReturnedBy != "" {
676			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
677		}
678	
679		// 先做全部校验，任何一件不满足都整批拒绝。
680		for _, id := range h.Parcels {
681			p, ok := s.data.Parcels[id]
682			if !ok {
683				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
684			}
685			if inc := activeFreeze(p); inc != "" {
686				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
687			}
688			if p.Station != h.To || p.Status != statusInStation {
689				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
690					id, p.Station, p.Status, h.To)
691			}
692			last := lastFlowEvent(p.Trail)
693			if last.Op != "交接" || last.Request != handoffReq {
694				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
695					id, handoffReq)
696			}
697		}
698	
699		res := &ReturnResult{
700			Request: request,
701			Handoff: handoffReq,
702			From:    h.To,
703			To:      h.From,
704			Reason:  reason,
705			Parcels: append([]string(nil), h.Parcels...),
706			Time:    now,
707		}
708		s.data.Returns[request] = res
709		h.ReturnedBy = request
710	
711		// 记录旧值，落盘失败时整体回滚。
712		prev := make(map[string]struct {
713			station string
714			trail   []Event
715		}, len(h.Parcels))
716		for _, id := range h.Parcels {
717			p := s.data.Parcels[id]
718			prev[id] = struct {
719				station string
720				trail   []Event
721			}{p.Station, append([]Event(nil), p.Trail...)}
722			p.Station = h.From
723			p.Status = statusInStation
724			p.Trail = append(p.Trail, Event{
725				Op:         "退回",
726				Station:    h.From,
727				From:       h.To,
728				Request:    request,
729				RefRequest: handoffReq,
730				Reason:     reason,
731				Time:       now,
732			})
733		}
734	
735		if err := s.save(); err != nil {
736			delete(s.data.Returns, request)
737			h.ReturnedBy = ""
738			for id, old := range prev {
739				p := s.data.Parcels[id]
740				p.Station = old.station
741				p.Trail = old.trail
742			}
743			return nil, false, err
744		}
745		return res, false, nil
746	}
747	
748	// Dispatch 提交一次配送批次出站。
749	//
750	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
751	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
752	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
753	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
754	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
755	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
756		if saved, ok := s.data.Batches[batch]; ok {
757			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
758				return saved, true, nil
759			}
760			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
761		}
762	
763		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
764		for _, id := range parcels {
765			p, ok := s.data.Parcels[id]
766			if !ok {
767				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
768			}
769			if p.Station != station {
770				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
771			}
772			if inc := activeFreeze(p); inc != "" {
773				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
774			}
775			if p.Status != statusInStation {
776				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
777			}
778		}
779	
780		res := &BatchResult{
781			Batch:    batch,
782			Station:  station,
783			Courier:  courier,
784			Parcels:  append([]string(nil), parcels...),
785			Time:     now,
786			Receipts: map[string]*ReceiptEntry{},
787		}
788		s.data.Batches[batch] = res
789	
790		// 记录旧值，落盘失败时整体回滚。
791		prev := make(map[string]struct {
792			status string
793			trail  []Event
794		}, len(parcels))
795		for _, id := range parcels {
796			p := s.data.Parcels[id]
797			prev[id] = struct {
798				status string
799				trail  []Event
800			}{p.Status, append([]Event(nil), p.Trail...)}
801			p.Status = statusDelivering // 站点不变，仍记出发站
802			p.Trail = append(p.Trail, Event{
803				Op:      "出站",
804				Station: station,
805				Batch:   batch,
806				Courier: courier,
807				Time:    now,
808			})
809		}
810	
811		if err := s.save(); err != nil {
812			delete(s.data.Batches, batch)
813			for id, old := range prev {
814				p := s.data.Parcels[id]
815				p.Status = old.status
816				p.Trail = old.trail
817			}
818			return nil, false, err
819		}
820		return res, false, nil
821	}
