		{"已完成批次不能中止", "A2", "B2", "原因"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if _, _, err := s.Abort(c.request, c.batch, c.reason, tClock(2026, 10, 5, 11, 0)); err == nil {
				t.Fatal("条件不满足时中止必须失败")
			}
			after, _ := os.ReadFile(path)
